head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_1', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_2_1').style.backgroundColor == "";
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 3. Test Data의 2번 샘플파일을 실행하고 대리점항목명을 마우스로 드래그하여 위로 올려서 groupby하고 가로스크롤을 좌우로 이동한다.(스크롤이 안생길경우 사이즈를 줄여서 확인한다.)
    //3. Execute sample file 2 of test data and drag the name of the agency item with mouse and move up to groupby and move the horizontal scroll to the left or right. (If it does not scroll, check the size by reducing it.)
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 오른쪽에서 첫번째 항목인 '판매액'항목이 고정되고 나머지 항목들이 이동되어진다.
    //4. On the right, the first item 'Sales' is fixed and the remaining items are moved.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 09-Mar-2018
    var valBeforeScoll, valAfterScoll;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
